--
-- 000_baseline_globals.sql — role, granty, default privileges
--
-- 000_baseline_20260730.sql byl pořízen s `--no-owner --no-privileges`,
-- takže NEobsahuje ani roli `tixly_app`, ani jediný GRANT. Bez tohohle
-- souboru vznikne kompletní schéma včetně 596 RLS policies a aplikace
-- se přesto nedostane k jedinému řádku.
--
-- POŘADÍ: tenhle soubor se pouští AŽ PO 000_baseline_20260730.sql —
-- granty se udělují na objekty, které musí existovat dřív.
-- Výjimka: CREATE ROLE níže nemá na schématu závislost a je idempotentní.
--
-- ⚠️ HESLO ROLE NENÍ V TOMHLE SOUBORU a nikdy tu být nesmí. Z pg_roles
--    ho vyčíst nelze. Při deployi vygenerovat, uložit do env a nastavit
--    samostatně: ALTER ROLE tixly_app WITH PASSWORD '<z env>';
--
-- Granty jsou PER TABULKU, ne `ON ALL TABLES IN SCHEMA`. Důvod: 7 tabulek
-- (communications.broadcasts, .emergency_announcements, .announcement_responses,
-- brands.advertisers, .campaigns, .event_partnerships, .impressions) dnes
-- grant NEMÁ. `ON ALL TABLES` by jim ho přidal = rozšíření oprávnění.
--
-- Vygenerováno z br-rough-paper-alom0zky 2026-07-30.
--

-- ── role ─────────────────────────────────────────────────────────────
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'tixly_app') THEN
    CREATE ROLE tixly_app LOGIN NOBYPASSRLS NOCREATEDB NOCREATEROLE;
  END IF;
END $$;

-- ── členství ─────────────────────────────────────────────────────────
GRANT tixly_app TO neondb_owner;

